package org.example.socialmediabackend.controller;
import org.example.socialmediabackend.model.User; import org.example.socialmediabackend.repository.UserRepository; import org.example.socialmediabackend.security.JwtUtil; import org.example.socialmediabackend.service.ApiMapper; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/auth") public class AuthController {
 private final UserRepository users;private final PasswordEncoder encoder;private final JwtUtil jwt;
 public AuthController(UserRepository users,PasswordEncoder encoder,JwtUtil jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
 @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Map<String,String> b){String full=clean(b.get("fullName")),username=clean(b.get("username")),email=clean(b.get("email")).toLowerCase(Locale.ROOT),password=b.get("password");if(full.isBlank()||username.length()<3||email.isBlank()||password==null||password.length()<6)return ResponseEntity.badRequest().body(Map.of("message","Full name, username, email and a password of at least 6 characters are required"));if(users.existsByEmailIgnoreCase(email))return ResponseEntity.status(409).body(Map.of("message","Email is already registered"));if(users.existsByUsernameIgnoreCase(username))return ResponseEntity.status(409).body(Map.of("message","Username is already taken"));User u=new User();u.setFullName(full);u.setUsername(username);u.setEmail(email);u.setPasswordHash(encoder.encode(password));u.setBio(clean(b.get("bio")));u=users.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","Registration successful","token",jwt.generateToken(u.getEmail()),"user",ApiMapper.user(u)));}
 @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Map<String,String> b){String email=clean(b.get("email"));String password=b.get("password");User u=users.findByEmailIgnoreCase(email).orElse(null);if(u==null||password==null||!encoder.matches(password,u.getPasswordHash()))return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));return ResponseEntity.ok(Map.of("message","Login successful","token",jwt.generateToken(u.getEmail()),"user",ApiMapper.user(u)));}
 private String clean(String s){return s==null?"":s.trim();}
}
